<script setup lang="ts">
import {
  APIProblem, activateIntegrationCredential, beginIntegrationAuthorization, confirmIntegrationResolution, createIntegrationConnection,
  disableIntegrationConnection, enableIntegrationConnection, getIntegrationAuthorization, getIntegrationConnection, getIntegrationExecution,
  listIntegrationConnections, listIntegrationExecutions, listIntegrationHealth, prepareIntegrationExecution, readIntegrationWeb,
  requestIntegrationResolution, reviseIntegrationConnection, revokeIntegrationConnection, revokeIntegrationCredential,
  rotateIntegrationCredential, searchIntegrationWeb,
  type IntegrationAuthorization, type IntegrationCapability, type IntegrationConnection, type IntegrationConnectionDetail,
  type IntegrationConnectionState, type IntegrationConnectorKind, type IntegrationExecutionDetail, type IntegrationExecutionState,
  type IntegrationHealthObservation, type IntegrationResolutionOutcome, type IntegrationWebResearchReadResult,
  type IntegrationWebResearchSearchItem
} from "@spyglass/api";
import { IoButton } from "@spyglass/design-system";
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useSessionStore } from "../stores/session";

type Tab = "connections" | "executions" | "research";
type Action = "connection-create" | "connection-edit" | "credential-bind" | "credential-rotate" | "connection-disable" | "connection-enable" | "connection-revoke" | "authorization-begin" | "credential-revoke" | "execution-prepare" | "resolution-request" | "resolution-confirm" | "research-capture";
const session = useSessionStore(); const route = useRoute(); const router = useRouter();
const connections = ref<ReadonlyArray<IntegrationConnection>>([]); const selectedConnection = ref<IntegrationConnectionDetail>(); const health = ref<ReadonlyArray<IntegrationHealthObservation>>([]);
const executions = ref<ReadonlyArray<IntegrationExecutionDetail["execution"]>>([]); const selectedExecution = ref<IntegrationExecutionDetail>(); const authorization = ref<IntegrationAuthorization>();
const researchResults = ref<ReadonlyArray<IntegrationWebResearchSearchItem>>([]); const captured = ref<IntegrationWebResearchReadResult>();
const connectionCursor = ref<string>(); const executionCursor = ref<string>(); const healthCursor = ref<string>(); const loadingMore = ref(false);
const tab = ref<Tab>("connections"); const connectionState = ref<"" | IntegrationConnectionState>(""); const connectionKind = ref<"" | IntegrationConnectorKind>(""); const executionState = ref<"" | IntegrationExecutionState>("");
const loading = ref(false); const saving = ref(false); const searching = ref(false); const error = ref(""); const announcement = ref(""); let sequence = 0;
let authorizationTimer: number | undefined; let authorizationPolls = 0;
const modalOpen = ref(false); const action = ref<Action>("connection-create"); const confirmation = ref("");
const name = ref(""); const kind = ref<IntegrationConnectorKind>("email"); const capabilities = ref<IntegrationCapability[]>(["email.read"]); const emailAddress = ref(""); const audienceReference = ref(""); const driveFolders = ref(""); const httpsOrigin = ref(""); const pathPrefix = ref("/");
const provider = ref(""); const referenceSHA256 = ref(""); const expiresAt = ref(""); const releaseID = ref(""); const releaseVersion = ref(1); const deliveryCapability = ref<"email.send" | "web.publish">("email.send"); const executionConnectionID = ref("");
const resolutionOutcome = ref<IntegrationResolutionOutcome>("succeeded"); const evidence = ref(""); const researchConnectionID = ref(""); const researchQuery = ref(""); const researchURL = ref(""); const authorizationURL = ref("");

const integrationsPackage = computed(() => session.selected?.entitlements.packages.find((item) => item.code === "integrations"));
const marketingPackage = computed(() => session.selected?.entitlements.packages.find((item) => item.code === "marketing"));
const knowledgePackage = computed(() => session.selected?.entitlements.packages.find((item) => item.code === "knowledge"));
const available = computed(() => Boolean(integrationsPackage.value && integrationsPackage.value.mode !== "suspended"));
const manageable = computed(() => integrationsPackage.value?.mode === "enabled" && ["owner", "administrator"].includes(session.selected?.role ?? ""));
const canPrepare = computed(() => manageable.value && marketingPackage.value?.mode === "enabled");
const canCapture = computed(() => integrationsPackage.value?.mode === "enabled" && knowledgePackage.value?.mode === "enabled" && ["owner", "administrator", "member"].includes(session.selected?.role ?? ""));
const activeResearchConnections = computed(() => connections.value.filter((item) => item.kind === "web_research" && item.state === "active"));
const deliveryConnections = computed(() => connections.value.filter((item) => item.state === "active" && (deliveryCapability.value === "email.send" ? item.kind === "email" : item.kind === "web_publish")));
const emailCapabilitiesValid = computed(() => kind.value !== "email" || capabilities.value.some((item) => item === "email.read" || item === "email.send"));
const formValid = computed(() => !["connection-create", "connection-edit"].includes(action.value) || emailCapabilitiesValid.value);

function label(value: string): string { return value.replaceAll("_", " ").replace(/^./, (first) => first.toUpperCase()); }
function date(value?: string): string { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "Not set"; }
function short(value?: string): string { return value ? `${value.slice(0, 8)}…${value.slice(-4)}` : "Not set"; }
function target(): { kind?: "connection" | "execution" | "authorization"; id?: string } {
  if (typeof route.params.connectionID === "string") return { kind: "connection", id: route.params.connectionID };
  if (typeof route.params.executionID === "string") return { kind: "execution", id: route.params.executionID };
  if (typeof route.params.authorizationID === "string") return { kind: "authorization", id: route.params.authorizationID };
  return {};
}
async function loadConnection(accountID: string, id: string): Promise<void> {
  selectedConnection.value = await getIntegrationConnection(accountID, id); health.value = [];
  const page = await listIntegrationHealth(accountID, id); health.value = page.items; healthCursor.value = page.next_cursor;
}
async function load(): Promise<void> {
  const accountID = session.selectedID; const current = ++sequence; connections.value = []; executions.value = []; selectedConnection.value = undefined; selectedExecution.value = undefined; authorization.value = undefined; health.value = []; connectionCursor.value = undefined; executionCursor.value = undefined; healthCursor.value = undefined; error.value = "";
  if (!accountID || !available.value) return; loading.value = true;
  try {
    const [connectionPage, executionPage] = await Promise.all([
      listIntegrationConnections(accountID, { state: connectionState.value || undefined, kind: connectionKind.value || undefined }),
      listIntegrationExecutions(accountID, { state: executionState.value || undefined })
    ]);
    if (current !== sequence) return; connections.value = connectionPage.items; connectionCursor.value = connectionPage.next_cursor; executions.value = executionPage.items; executionCursor.value = executionPage.next_cursor;
    const routeTarget = target();
    if (routeTarget.kind === "connection" && routeTarget.id) { tab.value = "connections"; await loadConnection(accountID, routeTarget.id); }
    else if (routeTarget.kind === "execution" && routeTarget.id) { tab.value = "executions"; selectedExecution.value = await getIntegrationExecution(accountID, routeTarget.id); }
    else if (routeTarget.kind === "authorization" && routeTarget.id) { tab.value = "connections"; authorization.value = await getIntegrationAuthorization(accountID, routeTarget.id); await loadConnection(accountID, authorization.value.connection_id); if (["pending", "exchanging"].includes(authorization.value.status)) startAuthorizationPolling(); }
    else if (connectionPage.items[0]) await loadConnection(accountID, connectionPage.items[0].id);
    researchConnectionID.value ||= activeResearchConnections.value[0]?.id ?? "";
  } catch (cause) { if (current === sequence) error.value = cause instanceof APIProblem ? cause.message : "Integrations are temporarily unavailable."; }
  finally { if (current === sequence) loading.value = false; }
}
async function loadMore(value: "connections" | "executions" | "health"): Promise<void> {
  const accountID = session.selectedID; if (!accountID || loadingMore.value) return; loadingMore.value = true;
  try {
    if (value === "connections" && connectionCursor.value) { const page = await listIntegrationConnections(accountID, { state: connectionState.value || undefined, kind: connectionKind.value || undefined, cursor: connectionCursor.value }); connections.value = [...connections.value, ...page.items]; connectionCursor.value = page.next_cursor; }
    if (value === "executions" && executionCursor.value) { const page = await listIntegrationExecutions(accountID, { state: executionState.value || undefined, cursor: executionCursor.value }); executions.value = [...executions.value, ...page.items]; executionCursor.value = page.next_cursor; }
    if (value === "health" && healthCursor.value && selectedConnection.value) { const page = await listIntegrationHealth(accountID, selectedConnection.value.connection.id, healthCursor.value); health.value = [...health.value, ...page.items]; healthCursor.value = page.next_cursor; }
  } catch (cause) { error.value = cause instanceof APIProblem ? cause.message : "More Integration records could not be loaded."; }
  finally { loadingMore.value = false; }
}
async function navigate(path: string): Promise<void> { if (route.path === path) await load(); else await router.push(path); }
function selectTab(value: Tab): void { tab.value = value; if (target().kind) void router.replace("/app/integrations"); }
function fixedCapabilities(value: IntegrationConnectorKind): IntegrationCapability[] { if (value === "google_drive") return ["google_drive.read"]; if (value === "web_research") return ["web.research"]; if (value === "web_publish") return ["web.publish"]; return capabilities.value.filter((item) => item === "email.read" || item === "email.send"); }
function scope() {
  if (kind.value === "email") return { email_address: emailAddress.value.trim(), ...(audienceReference.value.trim() ? { audience_reference: audienceReference.value.trim() } : {}) };
  if (kind.value === "google_drive") return { drive_folder_ids: driveFolders.value.split(/\r?\n/).map((item) => item.trim()).filter(Boolean) };
  return { https_origin: httpsOrigin.value.trim(), path_prefix: pathPrefix.value.trim() };
}
function resetForm(): void { confirmation.value = ""; error.value = ""; name.value = ""; kind.value = "email"; capabilities.value = ["email.read"]; emailAddress.value = ""; audienceReference.value = ""; driveFolders.value = ""; httpsOrigin.value = ""; pathPrefix.value = "/"; provider.value = ""; referenceSHA256.value = ""; expiresAt.value = ""; releaseID.value = ""; releaseVersion.value = 1; deliveryCapability.value = "email.send"; executionConnectionID.value = deliveryConnections.value[0]?.id ?? ""; resolutionOutcome.value = "succeeded"; evidence.value = ""; }
function begin(value: Action, item?: IntegrationWebResearchSearchItem): void {
  action.value = value; resetForm(); const detail = selectedConnection.value;
  if (value === "connection-edit" && detail) { name.value = detail.connection.name; kind.value = detail.connection.kind; capabilities.value = [...detail.revision.capabilities]; emailAddress.value = detail.revision.scope.email_address ?? ""; audienceReference.value = detail.revision.scope.audience_reference ?? ""; driveFolders.value = detail.revision.scope.drive_folder_ids?.join("\n") ?? ""; httpsOrigin.value = detail.revision.scope.https_origin ?? ""; pathPrefix.value = detail.revision.scope.path_prefix ?? "/"; }
  if (value === "credential-rotate" && detail) provider.value = detail.connection.kind === "email" ? "smtp" : detail.connection.kind === "web_publish" ? "http_publish" : "firecrawl";
  if (value === "credential-bind" && detail) provider.value = detail.connection.kind === "email" ? "smtp" : detail.connection.kind === "web_publish" ? "http_publish" : "firecrawl";
  if (value === "research-capture" && item) researchURL.value = item.url;
  modalOpen.value = true;
}
function phrase(): string { const values: Partial<Record<Action, string>> = { "connection-revoke": "REVOKE", "credential-revoke": "REVOKE", "authorization-begin": "CONNECT", "execution-prepare": "PREPARE", "resolution-request": "RESOLVE", "resolution-confirm": "CONFIRM", "research-capture": "CAPTURE" }; return values[action.value] ?? ""; }
function title(): string { return ({ "connection-create": "Create connection", "connection-edit": "Revise connection scope", "credential-bind": "Activate broker binding", "credential-rotate": "Rotate broker binding", "connection-disable": "Disable connection", "connection-enable": "Enable connection", "connection-revoke": "Revoke connection", "authorization-begin": "Connect Google Drive", "credential-revoke": "Revoke Google access", "execution-prepare": "Prepare external delivery", "resolution-request": "Propose observed outcome", "resolution-confirm": "Confirm observed outcome", "research-capture": "Capture source into Knowledge" } satisfies Record<Action, string>)[action.value]; }
function strongAuth(cause: unknown): boolean {
  if (!(cause instanceof APIProblem) || !["recent_passkey_required", "strong_reauthentication_required", "owner_security_enrollment_required"].includes(cause.problem?.code ?? "")) return false;
  window.location.assign(`/app/security?return_to=${encodeURIComponent(route.fullPath)}&status=${encodeURIComponent(cause.problem?.code ?? "strong_reauthentication_required")}`); return true;
}
async function submit(): Promise<void> {
  const accountID = session.selectedID; const detail = selectedConnection.value; const execution = selectedExecution.value; if (!accountID || saving.value || (phrase() && confirmation.value !== phrase()) || !formValid.value) return; saving.value = true; error.value = "";
  try {
    let path = route.path;
    if (action.value === "connection-create") { const value = await createIntegrationConnection(accountID, { name: name.value.trim(), kind: kind.value, capabilities: fixedCapabilities(kind.value), scope: scope() }); path = `/app/integrations/connections/${value.id}`; }
    else if (action.value === "connection-edit" && detail) await reviseIntegrationConnection(accountID, detail.connection, { name: name.value.trim(), capabilities: fixedCapabilities(kind.value), scope: scope() });
    else if (action.value === "credential-bind" && detail) await activateIntegrationCredential(accountID, detail.connection, { provider: provider.value.trim(), reference_sha256: referenceSHA256.value.trim(), ...(expiresAt.value ? { expires_at: new Date(expiresAt.value).toISOString() } : {}) });
    else if (action.value === "credential-rotate" && detail) await rotateIntegrationCredential(accountID, detail.connection, { expected_generation: detail.connection.credential_generation ?? 0, provider: provider.value.trim(), reference_sha256: referenceSHA256.value.trim(), ...(expiresAt.value ? { expires_at: new Date(expiresAt.value).toISOString() } : {}) });
    else if (action.value === "connection-disable" && detail) await disableIntegrationConnection(accountID, detail.connection);
    else if (action.value === "connection-enable" && detail) await enableIntegrationConnection(accountID, detail.connection);
    else if (action.value === "connection-revoke" && detail) await revokeIntegrationConnection(accountID, detail.connection);
    else if (action.value === "authorization-begin" && detail) { const callback = `${window.location.origin}/api/v1/accounts/${encodeURIComponent(accountID)}/integrations/google/authorization-callback`; const result = await beginIntegrationAuthorization(accountID, detail.connection.id, callback); const destination = new URL(result.authorization_url); if (destination.protocol !== "https:") throw new Error("The provider returned an unsafe authorization destination."); authorization.value = result.authorization; authorizationURL.value = destination.href; path = `/app/integrations/authorizations/${result.authorization.id}`; window.open(destination.href, "spyglass-google-authorization", "popup,width=720,height=780,noopener,noreferrer"); }
    else if (action.value === "credential-revoke" && detail) await revokeIntegrationCredential(accountID, detail.connection.id);
    else if (action.value === "execution-prepare") { const value = await prepareIntegrationExecution(accountID, { release_id: releaseID.value, release_version: releaseVersion.value, capability: deliveryCapability.value, connection_id: executionConnectionID.value }); path = `/app/integrations/executions/${value.id}`; }
    else if (action.value === "resolution-request" && execution) await requestIntegrationResolution(accountID, execution.execution.id, { requested_outcome: resolutionOutcome.value, evidence: evidence.value.trim() });
    else if (action.value === "resolution-confirm" && execution?.resolution) await confirmIntegrationResolution(accountID, execution.execution.id, execution.resolution.id);
    else if (action.value === "research-capture") { captured.value = await readIntegrationWeb(accountID, { connection_id: researchConnectionID.value, url: researchURL.value }); tab.value = "research"; }
    modalOpen.value = false; announcement.value = `${title()} completed.`; await navigate(path);
  } catch (cause) {
    if (strongAuth(cause)) return;
    if (cause instanceof APIProblem && cause.status === 409) { modalOpen.value = false; await load(); error.value = "This Integration record changed. Review its current state before trying again."; }
    else error.value = cause instanceof APIProblem ? cause.message : cause instanceof Error ? cause.message : "The Integration command could not be completed.";
  } finally { saving.value = false; }
}
function stopAuthorizationPolling(): void { if (authorizationTimer !== undefined) window.clearTimeout(authorizationTimer); authorizationTimer = undefined; }
function startAuthorizationPolling(): void { stopAuthorizationPolling(); authorizationPolls = 0; authorizationTimer = window.setTimeout(() => void pollAuthorization(), 1500); }
async function pollAuthorization(): Promise<void> { authorizationTimer = undefined; await refreshAuthorization(); authorizationPolls += 1; if (authorization.value && ["pending", "exchanging"].includes(authorization.value.status) && authorizationPolls < 60) authorizationTimer = window.setTimeout(() => void pollAuthorization(), 2000); }
async function refreshAuthorization(): Promise<void> { const accountID = session.selectedID; if (!accountID || !authorization.value) return; try { authorization.value = await getIntegrationAuthorization(accountID, authorization.value.id); if (authorization.value.status === "completed") { stopAuthorizationPolling(); announcement.value = "Google Drive authorization completed."; await loadConnection(accountID, authorization.value.connection_id); } else if (["failed", "expired"].includes(authorization.value.status)) stopAuthorizationPolling(); } catch (cause) { stopAuthorizationPolling(); error.value = cause instanceof APIProblem ? cause.message : "Authorization status could not be refreshed."; } }
async function search(): Promise<void> { const accountID = session.selectedID; if (!accountID || !researchConnectionID.value || searching.value) return; searching.value = true; error.value = ""; captured.value = undefined; try { const result = await searchIntegrationWeb(accountID, { connection_id: researchConnectionID.value, query: researchQuery.value.trim(), limit: 10 }); researchResults.value = result.items; announcement.value = `${result.items.length} scoped research results returned.`; } catch (cause) { error.value = cause instanceof APIProblem ? cause.message : "Scoped web research could not be completed."; } finally { searching.value = false; } }
watch(() => [session.selectedID, integrationsPackage.value?.mode, route.path, connectionState.value, connectionKind.value, executionState.value], () => void load(), { immediate: true });
onBeforeUnmount(stopAuthorizationPolling);
</script>

<template>
  <section class="page integrations-page">
    <p class="sr-only" aria-live="polite" aria-atomic="true">{{ announcement }}</p>
    <header class="page-heading page-heading--action"><div><p class="eyebrow">Integrations</p><h1>Connect deliberately. Observe every effect.</h1><p>Review non-secret provider scope, health and immutable delivery evidence without exposing credentials or silently resending uncertain effects.</p></div><span v-if="available" class="state-badge">{{ integrationsPackage?.mode === "enabled" ? "Package enabled" : "Read-only access" }}</span></header>
    <section v-if="!session.selectedID" class="queue-state"><h2>Select an Account</h2><p>Connections and external effects always belong to one Account.</p></section>
    <section v-else-if="!available" class="queue-state queue-state--locked"><h2>Integrations is not active</h2><p>Add the Integrations package to manage provider scope and execution evidence.</p><a href="/app/checkout">Review Account plans</a></section>
    <template v-else>
      <section v-if="session.selected?.owner_enrollment_required" class="queue-state queue-state--warning"><h2>Secure this owner Account first</h2><p>Add a passkey and save recovery codes before changing connector authority.</p><a href="/app/security?return_to=%2Fapp%2Fintegrations">Continue security setup</a></section>
      <p v-if="error" class="queue-inline-status queue-inline-status--error" role="alert">{{ error }}</p>
      <div class="finance-tabs" role="tablist" aria-label="Integration workspace"><button type="button" role="tab" :aria-selected="tab === 'connections'" @click="selectTab('connections')">Connections</button><button type="button" role="tab" :aria-selected="tab === 'executions'" @click="selectTab('executions')">Executions</button><button type="button" role="tab" :aria-selected="tab === 'research'" @click="selectTab('research')">Research</button></div>
      <div v-if="loading" class="queue-state" role="status">Loading governed Integration state…</div>
      <section v-else-if="tab === 'connections'" class="finance-workspace integrations-workspace">
        <div class="finance-list-panel"><header><div><p class="eyebrow">Connections</p><h2>Scope and authority</h2></div><IoButton v-if="manageable" @click="begin('connection-create')">New connection</IoButton></header><div class="integration-filters"><label>State<select v-model="connectionState"><option value="">All states</option><option value="pending">Pending</option><option value="active">Active</option><option value="disabled">Disabled</option><option value="revoked">Revoked</option></select></label><label>Kind<select v-model="connectionKind"><option value="">All kinds</option><option value="email">Email</option><option value="google_drive">Google Drive</option><option value="web_research">Web research</option><option value="web_publish">Web publication</option></select></label></div><ol><li v-for="item in connections" :key="item.id"><button type="button" @click="navigate(`/app/integrations/connections/${item.id}`)"><span><strong>{{ item.name }}</strong><small>{{ label(item.kind) }} · revision {{ item.current_revision }}</small></span><em>{{ label(item.state) }}</em></button></li></ol><p v-if="connections.length === 0">No connections match this view.</p><IoButton v-if="connectionCursor" kind="secondary" :disabled="loadingMore" @click="loadMore('connections')">Load more connections</IoButton></div>
        <aside class="finance-detail integrations-detail"><template v-if="selectedConnection"><p class="eyebrow">Connection detail</p><h2>{{ selectedConnection.connection.name }}</h2><p>Only non-secret scope, revision evidence and credential identity are visible.</p><dl><div><dt>State</dt><dd>{{ label(selectedConnection.connection.state) }}</dd></div><div><dt>Kind</dt><dd>{{ label(selectedConnection.connection.kind) }}</dd></div><div><dt>Capabilities</dt><dd>{{ selectedConnection.revision.capabilities.join(" · ") }}</dd></div><div><dt>Revision</dt><dd>{{ selectedConnection.connection.current_revision }}</dd></div><div><dt>Credential generation</dt><dd>{{ selectedConnection.connection.credential_generation ?? "Not bound" }}</dd></div><div v-if="selectedConnection.revision.scope.email_address"><dt>Email</dt><dd>{{ selectedConnection.revision.scope.email_address }}</dd></div><div v-if="selectedConnection.revision.scope.audience_reference"><dt>Audience</dt><dd>{{ selectedConnection.revision.scope.audience_reference }}</dd></div><div v-if="selectedConnection.revision.scope.drive_folder_ids?.length"><dt>Drive folders</dt><dd>{{ selectedConnection.revision.scope.drive_folder_ids.join(" · ") }}</dd></div><div v-if="selectedConnection.revision.scope.https_origin"><dt>Origin</dt><dd>{{ selectedConnection.revision.scope.https_origin }}{{ selectedConnection.revision.scope.path_prefix }}</dd></div></dl><div v-if="manageable && selectedConnection.connection.state !== 'revoked'" class="finance-detail-actions"><IoButton kind="secondary" @click="begin('connection-edit')">Revise scope</IoButton><IoButton v-if="selectedConnection.connection.kind === 'google_drive'" @click="begin('authorization-begin')">{{ selectedConnection.connection.state === "pending" ? "Connect Google Drive" : "Reconnect Google" }}</IoButton><IoButton v-else-if="selectedConnection.connection.state === 'pending'" @click="begin('credential-bind')">Activate binding</IoButton><IoButton v-else-if="['active', 'disabled'].includes(selectedConnection.connection.state)" kind="secondary" @click="begin('credential-rotate')">Rotate binding</IoButton><IoButton v-if="selectedConnection.connection.state === 'active'" kind="secondary" @click="begin('connection-disable')">Disable</IoButton><IoButton v-if="selectedConnection.connection.state === 'disabled'" kind="secondary" @click="begin('connection-enable')">Enable</IoButton><IoButton v-if="selectedConnection.connection.kind === 'google_drive' && selectedConnection.connection.credential_id" kind="secondary" @click="begin('credential-revoke')">Revoke Google access</IoButton><IoButton kind="secondary" @click="begin('connection-revoke')">Revoke connection</IoButton></div><section v-if="authorization" class="integration-authorization" aria-live="polite"><h3>Google authorization</h3><p><strong>{{ label(authorization.status) }}</strong> · expires {{ date(authorization.expires_at) }}</p><p v-if="['pending', 'exchanging'].includes(authorization.status)">Complete consent in the Google window; this status refreshes automatically.</p><p v-if="authorization.error_code">{{ label(authorization.error_code) }}</p><a v-if="authorizationURL && authorization.status === 'pending'" :href="authorizationURL" target="_blank" rel="noopener noreferrer">Open Google consent</a><IoButton v-if="['pending', 'exchanging'].includes(authorization.status)" kind="secondary" @click="refreshAuthorization">Check status</IoButton></section><section class="integration-health"><h3>Health history</h3><ol><li v-for="item in health" :key="item.id"><strong>{{ label(item.state) }}</strong><span>{{ item.latency_milliseconds }} ms · {{ date(item.checked_at) }}</span><small v-if="item.error_code">{{ item.error_code }}</small></li></ol><p v-if="health.length === 0">No health observation has been recorded.</p><IoButton v-if="healthCursor" kind="secondary" :disabled="loadingMore" @click="loadMore('health')">Load more health</IoButton></section></template><template v-else><p class="eyebrow">Connection detail</p><h2>Select a connection</h2><p>Inspect exact scope, credential generation and provider health.</p></template></aside>
      </section>
      <section v-else-if="tab === 'executions'" class="finance-workspace integrations-workspace"><div class="finance-list-panel"><header><div><p class="eyebrow">External executions</p><h2>Delivery evidence</h2></div><IoButton v-if="canPrepare" @click="begin('execution-prepare')">Prepare delivery</IoButton></header><label>State<select v-model="executionState"><option value="">All states</option><option v-for="value in ['prepared','executing','reconciling','retry_wait','unknown','manual_resolution','succeeded','failed','cancelled']" :key="value" :value="value">{{ label(value) }}</option></select></label><ol><li v-for="item in executions" :key="item.id"><button type="button" @click="navigate(`/app/integrations/executions/${item.id}`)"><span><strong>{{ item.capability }} · release v{{ item.release_version }}</strong><small>{{ short(item.id) }} · {{ item.attempt_count }} attempts · {{ date(item.updated_at) }}</small></span><em>{{ label(item.state) }}</em></button></li></ol><p v-if="executions.length === 0">No external executions match this view.</p><IoButton v-if="executionCursor" kind="secondary" :disabled="loadingMore" @click="loadMore('executions')">Load more executions</IoButton></div><aside class="finance-detail integrations-detail"><template v-if="selectedExecution"><p class="eyebrow">Execution detail</p><h2>{{ selectedExecution.execution.capability }} · {{ label(selectedExecution.execution.state) }}</h2><dl><div><dt>Release</dt><dd>{{ short(selectedExecution.execution.release_id) }} · v{{ selectedExecution.execution.release_version }}</dd></div><div><dt>Connection</dt><dd>{{ short(selectedExecution.execution.connection_id) }} · revision {{ selectedExecution.execution.connection_revision }}</dd></div><div><dt>Credential</dt><dd>Generation {{ selectedExecution.execution.credential_generation }}</dd></div><div><dt>Payload SHA-256</dt><dd>{{ selectedExecution.execution.payload_sha256 }}</dd></div><div><dt>Last error</dt><dd>{{ selectedExecution.execution.last_error_code ?? "None" }}</dd></div><div><dt>Completed</dt><dd>{{ date(selectedExecution.execution.completed_at) }}</dd></div></dl><section class="integration-attempts"><h3>Attempts</h3><ol><li v-for="item in selectedExecution.attempts" :key="item.id"><strong>#{{ item.number }} {{ label(item.mode) }}</strong><span>{{ item.outcome ? label(item.outcome) : "In flight" }}</span><small v-if="item.error_code">{{ item.error_code }}</small></li></ol><p v-if="selectedExecution.attempts.length === 0">No provider attempt has started.</p></section><section v-if="selectedExecution.resolution" class="integration-authorization"><h3>Manual resolution</h3><p>{{ label(selectedExecution.resolution.requested_outcome) }} · {{ label(selectedExecution.resolution.state) }}</p><code>{{ selectedExecution.resolution.evidence_sha256 }}</code><p v-if="selectedExecution.resolution.state === 'pending' && selectedExecution.resolution.requested_by_user_id === session.userID">A different owner or administrator must confirm this exact outcome.</p><IoButton v-else-if="manageable && selectedExecution.resolution.state === 'pending'" @click="begin('resolution-confirm')">Confirm exact outcome</IoButton></section><IoButton v-else-if="manageable && selectedExecution.execution.state === 'manual_resolution'" @click="begin('resolution-request')">Propose resolution</IoButton></template><template v-else><p class="eyebrow">Execution detail</p><h2>Select an execution</h2><p>Inspect frozen authority, provider attempts and dual-controlled recovery evidence.</p></template></aside></section>
      <section v-else class="integration-research"><div class="integration-research-intro"><div><p class="eyebrow">Scoped public research</p><h2>Search inside reviewed boundaries</h2><p>Search uses the selected connection’s exact HTTPS origin and path scope. Capturing a result creates immutable internal Knowledge evidence; it never broadens provider authority.</p></div><span class="state-badge">{{ canCapture ? "Knowledge capture enabled" : "Search only" }}</span></div><form class="integration-search" @submit.prevent="search"><label>Research connection<select v-model="researchConnectionID" required><option value="">Choose connection</option><option v-for="item in activeResearchConnections" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Question or search terms<input v-model="researchQuery" maxlength="500" required></label><IoButton type="submit" :disabled="searching || !activeResearchConnections.length">{{ searching ? "Searching…" : "Search" }}</IoButton></form><p v-if="!activeResearchConnections.length" class="queue-inline-status">An active Web research connection is required.</p><ol class="integration-search-results"><li v-for="item in researchResults" :key="item.citation_id"><div><strong>{{ item.title }}</strong><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.url }}</a><p>{{ item.description || "No provider description." }}</p><small>Retrieved {{ date(item.retrieved_at) }}</small></div><IoButton v-if="canCapture" kind="secondary" @click="begin('research-capture', item)">Capture to Knowledge</IoButton></li></ol><section v-if="captured" class="integration-capture-result" role="status"><p class="eyebrow">Knowledge evidence captured</p><h3>{{ captured.title }}</h3><p>{{ captured.excerpt || captured.url }}</p><dl><div><dt>Document</dt><dd>{{ captured.document_id }}</dd></div><div><dt>Revision</dt><dd>{{ captured.document_revision_id }}</dd></div><div><dt>Content SHA-256</dt><dd>{{ captured.content_sha256 }}</dd></div></dl><a href="/app/knowledge">Review Knowledge</a></section></section>
    </template>
    <div v-if="modalOpen" class="modal-backdrop"><form class="modal-card integration-modal" role="dialog" aria-modal="true" aria-labelledby="integration-modal-title" @submit.prevent="submit"><h2 id="integration-modal-title">{{ title() }}</h2><template v-if="['connection-create','connection-edit'].includes(action)"><label>Name<input v-model="name" maxlength="160" required></label><label v-if="action === 'connection-create'">Connector<select v-model="kind"><option value="email">Email</option><option value="google_drive">Google Drive</option><option value="web_research">Web research</option><option value="web_publish">Web publication</option></select></label><fieldset v-if="kind === 'email'"><legend>Capabilities</legend><label class="confirmation"><input v-model="capabilities" type="checkbox" value="email.read"><span>Read inbound email</span></label><label class="confirmation"><input v-model="capabilities" type="checkbox" value="email.send"><span>Send governed email</span></label><p v-if="!emailCapabilitiesValid" class="form-error">Choose at least one email capability.</p></fieldset><label v-if="kind === 'email'">Email address<input v-model="emailAddress" type="email" maxlength="320" required></label><label v-if="kind === 'email' && capabilities.includes('email.send')">Audience reference<input v-model="audienceReference" maxlength="500" required></label><label v-if="kind === 'google_drive'">Google Drive folder IDs, one per line<textarea v-model="driveFolders" rows="5" maxlength="10049" required></textarea></label><template v-if="['web_research','web_publish'].includes(kind)"><label>HTTPS origin<input v-model="httpsOrigin" type="url" maxlength="500" required></label><label>Path prefix<input v-model="pathPrefix" maxlength="500" pattern="/.*" required></label></template><p class="form-note">This form accepts only visible scope. Never paste a provider key, token, password or payload.</p></template><template v-else-if="['credential-bind','credential-rotate'].includes(action)"><label>Provider code<input v-model="provider" pattern="[a-z][a-z0-9_.]{0,63}" required></label><label>Broker reference SHA-256<input v-model="referenceSHA256" pattern="[0-9a-f]{64}" required></label><label>Expires at<input v-model="expiresAt" type="datetime-local"></label><p class="form-note">Enter only the reviewed digest of a secret-broker reference.</p></template><template v-else-if="action === 'execution-prepare'"><label>Approved Marketing release ID<input v-model="releaseID" pattern="[0-9a-fA-F-]{36}" required></label><label>Release version<input v-model="releaseVersion" type="number" min="1" required></label><label>Capability<select v-model="deliveryCapability"><option value="email.send">Email send</option><option value="web.publish">Web publish</option></select></label><label>Active connection<select v-model="executionConnectionID" required><option v-for="item in deliveryConnections" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><p class="form-note">Preparation freezes release, approval, scope revision, credential generation and content digest.</p></template><template v-else-if="action === 'resolution-request'"><label>Observed outcome<select v-model="resolutionOutcome"><option value="succeeded">Applied successfully</option><option value="failed">Did not succeed</option></select></label><label>Evidence<textarea v-model="evidence" minlength="3" maxlength="1000" rows="4" required></textarea></label><p class="form-note">This does not resend the operation. A different manager must confirm it.</p></template><p v-else-if="action === 'research-capture'">Fetch <strong>{{ researchURL }}</strong> inside the reviewed connection scope and admit its content as internal Knowledge evidence.</p><p v-else-if="action === 'authorization-begin'">Open Google’s consent page for this exact Drive scope. Spyglass stores provider credentials only in its encrypted broker.</p><p v-else-if="action === 'credential-revoke'">Revoke the current Google credential, fence its broker generation, and stop new Drive work. Existing captured Knowledge remains.</p><p v-else-if="action === 'resolution-confirm'">Confirm the exact externally observed outcome. You must be different from the manager who proposed it.</p><p v-else>{{ action === 'connection-disable' ? 'Pause new work while preserving history and credential binding.' : action === 'connection-enable' ? 'Resume work with the current reviewed scope and binding.' : 'Revocation is permanent and preserves immutable execution history.' }}</p><label v-if="phrase()">Type {{ phrase() }} to confirm<input v-model="confirmation" autocomplete="off" :pattern="phrase()" required></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="modal-actions"><IoButton type="button" kind="secondary" @click="modalOpen = false">Back</IoButton><IoButton type="submit" :disabled="saving || !formValid || (Boolean(phrase()) && confirmation !== phrase())">{{ saving ? "Saving…" : title() }}</IoButton></div></form></div>
  </section>
</template>
